// Sparse TF-card image store for simulation (generated by make_sd_images.py).
// +IMG=<dir> selects <dir>/index.txt and <dir>/data.hex; absent sectors read 0.
module sd_image_store;
    localparam integer MAXB = 12000*512;
    localparam integer MAXE = 64;
    reg [7:0] mem [0:MAXB-1];
    integer ext_s [0:MAXE-1];
    integer ext_n [0:MAXE-1];
    integer ext_o [0:MAXE-1];
    integer n_ext;
    reg [7:0] sbuf [0:511];
    string dir;
    initial begin : load
        integer fd, i, r;
        if (!$value$plusargs("IMG=%s", dir)) $fatal(1, "missing +IMG=<dir>");
        fd = $fopen({dir, "/index.txt"}, "r");
        if (fd == 0) $fatal(1, "cannot open index");
        r = $fscanf(fd, "%d", n_ext);
        if (n_ext > MAXE) $fatal(1, "too many extents");
        for (i = 0; i < n_ext; i = i + 1) r = $fscanf(fd, "%d %d %d", ext_s[i], ext_n[i], ext_o[i]);
        $fclose(fd);
        $readmemh({dir, "/data.hex"}, mem);
        $display("[store] %s extents=%0d", dir, n_ext);
    end
    task fetch(input [31:0] sec);
        integer i, k, base;
        begin
            base = -1;
            for (i = 0; i < n_ext; i = i + 1)
                if (sec >= ext_s[i] && sec < ext_s[i] + ext_n[i]) base = (ext_o[i] + (sec - ext_s[i])) * 512;
            for (k = 0; k < 512; k = k + 1) sbuf[k] = (base < 0) ? 8'h00 : mem[base + k];
        end
    endtask
endmodule
